  /**
   * Unique symbol used as the key for the `PopulatedDocumentMarker`. Because it is a
   * `unique symbol`, the marker is invisible at runtime and does not collide with any
   * real document property.
   */
  const populatedDocumentMarker: unique symbol;

  /**
   * A type marker attached to populated document types. It carries both the populated raw
   * document type and the original depopulated raw document type as invisible (phantom)
   * metadata via a `unique symbol` key. This lets `toObject()` / `toJSON()` resolve the
   * correct return type depending on whether `depopulate: true` was passed.
   *
   * Strip the marker externally via `Omit<..., keyof PopulatedDocumentMarker<any, any>>`.
   */
  export type PopulatedDocumentMarker<PopulatedRawDocType, DepopulatedRawDocType> = {
    [populatedDocumentMarker]: {
      populated: PopulatedRawDocType;
      depopulated: DepopulatedRawDocType;
    };
  };

  /**
   * Extracts the plain object type from a `Document` intersection type. If `T` extends some
   * `ObjectType & Document`, returns `FlatRecord<ObjectType>`; otherwise returns `T` unchanged.
   */
  export type ExtractDocumentObjectType<T> = T extends Document
    ? T extends infer ObjectType & Document
      ? FlatRecord<ObjectType>
      : FlatRecord<T>
    : T;

  /**
   * Recursively converts a populate `Paths` type (which may contain `Document` instances,
   * `DocumentArray`s, plain arrays, or nested objects) into a plain raw document type suitable
   * for use as the populated raw doc type.
   */
  export type PopulatePathToRawDocType<T> = T extends Document
    ? ExtractDocumentObjectType<T>
    : T extends Types.DocumentArray<infer ItemType>
      ? PopulatePathToRawDocType<ItemType>[]
      : T extends Array<infer ItemType>
        ? PopulatePathToRawDocType<ItemType>[]
        : T extends Record<string, any>
          ? { [K in keyof T]: PopulatePathToRawDocType<T[K]> }
          : T;

  /**
   * Computes the raw doc type for a document after population by merging `RawDocType` with the
   * POJO form of the populated paths.
