  export type PopulatedPathsDocumentType<RawDocType, Paths> =
    FlatRecord<MergeType<RawDocType, PopulatePathToRawDocType<Paths>>>;

  /**
   * The result type of a populate operation. Combines the document with the populated paths (via
   * `MergeType`, preserving the document methods) and attaches a `PopulatedDocumentMarker` carrying
   * both the populated and depopulated raw doc types.
